import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../repositories/providers.dart';
class JobsScreen extends ConsumerWidget{const JobsScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Jobs and Side Hustles')),body:ListView(padding:const EdgeInsets.all(16),children:[const TextField(decoration:InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search jobs, location or type')),for(final j in ref.watch(mockRepositoryProvider).jobs()) ZayloCard(child:ListTile(title:Text(j.title),subtitle:Text('${j.company}\n${j.location} • ${j.type}\nPosted ${j.posted.day}/${j.posted.month} • closes ${j.closing.day}/${j.closing.month}'),isThreeLine:true,trailing:IconButton(onPressed:()=>showComingSoon(context,'Save/report/apply'),icon:const Icon(Icons.bookmark_border))))]));}
